import {
  Entity,
  Enum,
  Index,
  PrimaryKey,
  Property,
} from '@mikro-orm/decorators/legacy';
import { OutboxStatus } from '../outbox-status.enum';

@Entity({ tableName: 'outbox_events' })
@Index({
  name: 'outbox_events_aggregate_idx',
  properties: ['aggregateType', 'aggregateId', 'sequence'],
})
export class MikroOutboxEvent {
  @PrimaryKey({ type: 'uuid' })
  id!: string;

  /**
   * Generated by the database (`generated always as identity`). It is used to
   * process events in insertion order and is never written by the application.
   */
  @Property({ type: 'bigint', persist: false })
  sequence!: string;

  @Property({ fieldName: 'event_type', type: 'string', length: 200 })
  eventType!: string;

  @Property({ fieldName: 'event_version', type: 'integer', default: 1 })
  eventVersion = 1;

  @Property({ fieldName: 'aggregate_type', type: 'string', length: 100 })
  aggregateType!: string;

  @Property({ fieldName: 'aggregate_id', type: 'string', length: 255 })
  aggregateId!: string;

  @Property({ type: 'jsonb' })
  payload: Record<string, unknown> = {};

  @Property({ type: 'jsonb', defaultRaw: "'{}'::jsonb" })
  headers: Record<string, unknown> = {};

  @Property({ fieldName: 'occurred_at', type: 'timestamptz' })
  occurredAt!: Date;

  @Enum({ items: () => OutboxStatus })
  status: OutboxStatus = OutboxStatus.PENDING;

  @Property({ type: 'integer', default: 0 })
  attempts = 0;

  @Property({
    fieldName: 'available_at',
    type: 'timestamptz',
    defaultRaw: 'now()',
  })
  availableAt: Date = new Date();

  @Property({ fieldName: 'locked_at', type: 'timestamptz', nullable: true })
  lockedAt!: Date | null;

  @Property({
    fieldName: 'locked_by',
    type: 'string',
    length: 100,
    nullable: true,
  })
  lockedBy!: string | null;

  @Property({ fieldName: 'processed_at', type: 'timestamptz', nullable: true })
  processedAt!: Date | null;

  @Property({ fieldName: 'last_error', type: 'text', nullable: true })
  lastError!: string | null;

  @Property({
    fieldName: 'created_at',
    type: 'timestamptz',
    onCreate: () => new Date(),
  })
  createdAt: Date = new Date();
}
